import{z as s,x as A,o as E,c as d,q as B,j as o,D as e,d as r,s as t,S as l,b as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"宏观审慎政策","description":"","frontmatter":{"title":"宏观审慎政策","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/macroprudential.md","filePath":"econ/macroprudential.md","lastUpdated":1791063341000}'),p={name:"econ/macroprudential.md"};function m(D,a,c,T,h,u){const i=A("Mermaid");return E(),d("div",null,[a[2]||(a[2]=B('<h1 id="宏观审慎政策" tabindex="-1">宏观审慎政策 <a class="header-anchor" href="#宏观审慎政策" aria-label="Permalink to &quot;宏观审慎政策&quot;">​</a></h1><div class="epigraph"><p>对杠杆的约束是总量状态上的政策，目标是外部性：火线出售与中介净值的价格影响未进入私人一阶条件。</p><footer>—— Bianchi and Mendoza；Jeanne and Korinek 的杠杆外部性；Basel III 的逆周期缓冲作为制度对照</footer></div><p><a href="/econ/eggertsson-krugman">上一课</a>的 \\(\\bar b\\) 突然下降是灾难。本课缺口是<strong>事前</strong>把 \\(\\bar b\\) 或银行 \\(\\phi\\) 当成工具：宏观审慎。不重推 ZLB 乘数，不写巴塞尔每一条会计。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>KM/GK/住房 LTV 里，私人借款人与银行不内化 \\(q\\) 与净值的价格效应。繁荣时过度杠杆，崩溃时放大。审慎：逆周期 LTV、资本缓冲、保证金。与货币政策分工：利率是粗工具，同时管通胀与杠杆会冲突（Tinbergen）。缺口是给「金融稳定政策」一条外部性语言，而不是把所有稳定都交给泰勒规则。</p><p><span class="marginnote">术语翻译：LTV（贷款价值比）就是「最多能借到抵押物估值的几成」。LTV=70% 意味着 100 万的房子最多借 70 万；房价一跌 20%，安全垫只剩 10 万。逆周期 LTV 就是在繁荣期把这个成数压低、给下跌提前留缓冲，跌时再放松以免踩踏。</span></p><p><span class="marginnote">Jeanne and Korinek；Bianchi, <em>AER</em> 2011 过度借贷。Farhi and Werning 的宏观审慎与货币。Galati and Moessner 综述。Basel III CCyB 是制度，不是本课推导出来的最优税率。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>福利：比较竞争均衡与计划者，得到对债务的 Pigou 税或数量限制。定量：在 Iacoviello 或 GK 里对 LTV、资本要求做 Ramsey 或简单规则。与 ZLB：事前审慎减少事后陷阱的概率，与事后财政是互补。开放：资本流入税是同一外部性的跨境版（后课全球金融周期）。</p>',9)),(E(),o(l,null,{default:e(()=>[t(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXT%5B%22%E6%9D%A0%E6%9D%86%E5%A4%96%E9%83%A8%E6%80%A7%22%5D%20--%3E%20TOOL%5B%22LTV%20%2F%20%E8%B5%84%E6%9C%AC%20%2F%20%E4%BF%9D%E8%AF%81%E9%87%91%22%5D%0A%20%20TOOL%20--%3E%20LEV%5B%22%E7%B9%81%E8%8D%A3%E6%9C%9F%E6%9D%A0%E6%9D%86%22%5D%0A%20%20MP%5B%22%E5%88%A9%E7%8E%87%22%5D%20--%3E%20BOTH%5B%22%E9%80%9A%E8%83%80%E4%B8%8E%E6%9D%A0%E6%9D%86%E5%86%B2%E7%AA%81%22%5D%0A%20%20TOOL%20--%3E%20DIV%5B%22%E5%B7%A5%E5%85%B7%E5%88%86%E5%B7%A5%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("p",null,"识别：审慎工具的宏观 IRF 短、内生性强，叙事与跨国差异（英国 FPC、香港 LTV）比 SVAR 更常用。",-1)),a[4]||(a[4]=n("h2",{id:"机制",tabindex:"-1"},[r("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=n("p",null,"机制是把约束当政策而非当技术。过紧：正常时期投资与住房服务损失；过松：崩溃概率。偶尔绑定使最优政策本身状态依存：松约束世界里审慎几乎无成本也无收益。预期：若审慎被预见为「繁荣必收」，可抑制诊断性房价过冲。",-1)),(E(),o(l,null,{default:e(()=>[t(i,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E8%B4%9F%E5%90%91%E5%86%B2%E5%87%BB%22%5D%20--%3E%20N%5B%22%E4%B8%AD%E4%BB%8B%E5%87%80%E5%80%BC%E4%B8%8B%E9%99%8D%22%5D%0A%20%20N%20--%3E%20C%5B%22%E8%A2%AB%E8%BF%AB%E7%81%AB%E7%BA%BF%E5%87%BA%E5%94%AE%E8%B5%84%E4%BA%A7%22%5D%0A%20%20C%20--%3E%20P%5B%22%E8%B5%84%E4%BA%A7%E4%BB%B7%E6%A0%BC%20q%20%E4%B8%8B%E8%B7%8C%22%5D%0A%20%20P%20--%3E%20N2%5B%22%E5%85%B6%E4%BB%96%E4%B8%AD%E4%BB%8B%E5%87%80%E5%80%BC%E5%86%8D%E8%A2%AB%E5%8E%8B%E4%BD%8E%22%5D%0A%20%20N2%20--%3E%20C%0A%20%20P%20--%3E%20X%5B%22%E5%8D%95%E4%B8%AA%E4%B8%AD%E4%BB%8B%E5%86%B3%E7%AD%96%E6%97%B6%E4%B8%8D%E8%AE%A1%E8%87%AA%E5%B7%B1%E5%AF%B9%20q%20%E7%9A%84%E5%BD%B1%E5%93%8D%20%3D%20%E5%A4%96%E9%83%A8%E6%80%A7%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p>与 HANK：LTV 主要绑中产住房借款人，分配效应明显，不是代表性福利能概括。</p><p><span class="marginnote">直觉类比：火线出售像剧院失火时人人冲向同一扇门——单个观众「尽快离场」是理性的，但所有人同时冲会把门堵死。资产价格就是那扇门：每个中介单独看都该卖出止损，可大家一起卖就把价格砸穿，反过来压低所有人的净值，逼出更多卖单。</span></p><p><span class="marginnote">本课不把微观审慎（单家银行风险）与宏观审慎（周期与系统）混成一词。前者已有资本监管课接口。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不定 CCyB 的基点。不写全部宏观审慎工具箱清单。影子银行会绕开（后课）。货币主导与财政主导会限制谁有工具。下一课把同一外部性放到跨境资本流。</p><p><span class="marginnote">常见误区：初学者容易把宏观审慎当成「更严的货币政策」。两者工具与目标都不同：利率管总量需求与通胀，LTV 与资本缓冲管杠杆结构与外部性；想用加息去拆房价泡沫，会连就业、汇率一并误伤——这正是 Tinbergen「几个目标就配几个工具」在此处的含义。</span></p><p>后课默认：宏观审慎针对杠杆外部性，与利率分工。下一课：全球金融周期。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>杠杆有价格外部性，审慎是 Pigou 或数量工具。</li><li>与货币政策分工，因工具与目标数量。</li><li>过紧有稳态成本；状态依存是关键。</li><li>出处：Bianchi；Jeanne and Korinek；Farhi and Werning。</li></ul>',9))])}const g=s(p,[["render",m]]);export{f as __pageData,g as default};
